DROP DATABASE papeleria;

-- Crear la base de datos si no existe
CREATE DATABASE IF NOT EXISTS papeleria;
USE papeleria;

-- Tabla de marcas
CREATE TABLE IF NOT EXISTS marcas (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(255) NOT NULL UNIQUE,
   habilitado TINYINT DEFAULT 1
);

-- Tabla de categorías
CREATE TABLE IF NOT EXISTS categorias (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(255) NOT NULL UNIQUE,
    habilitado TINYINT DEFAULT 1
);

-- Tabla de productos
CREATE TABLE IF NOT EXISTS productos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    codigo VARCHAR(50) NOT NULL UNIQUE,
    nombre VARCHAR(255) NOT NULL UNIQUE,
    precio DECIMAL(10, 2) NOT NULL,
    stock INT DEFAULT 0,
    detalle TEXT,
    habilitado TINYINT DEFAULT 1,
    idmarca INT,
    idcategoria INT,
    FOREIGN KEY (idmarca) REFERENCES marcas(id),
    FOREIGN KEY (idcategoria) REFERENCES categorias(id)
);

-- Tabla de imágenes de productos
CREATE TABLE IF NOT EXISTS imagenes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    idproducto INT NOT NULL,
    url VARCHAR(255) NOT NULL,
    FOREIGN KEY (idproducto) REFERENCES productos(id)
);

-- Tabla de estados de pedido
CREATE TABLE IF NOT EXISTS estado_pedidos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(255) NOT NULL
);

-- Tabla de pedidos
CREATE TABLE IF NOT EXISTS pedidos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    dni VARCHAR(20) NOT NULL,             -- DNI del cliente
    contacto VARCHAR(255) NOT NULL,       -- Información de contacto
    fecha DATE NOT NULL,                  -- Fecha del pedido
    hora TIME NOT NULL,                   -- Hora del pedido
    total DECIMAL(10, 2) NOT NULL,        -- Total del pedido
    idestado INT NOT NULL,                -- Estado del pedido
    FOREIGN KEY (idestado) REFERENCES estado_pedidos(id)
);

-- Tabla de detalles de pedidos
CREATE TABLE IF NOT EXISTS detalles_pedidos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    idproducto INT NOT NULL,              -- Producto relacionado
    precio DECIMAL(10, 2) NOT NULL,       -- Precio al momento del pedido
    cantidad INT NOT NULL CHECK (cantidad > 0),                -- Cantidad del producto
    subtotal DECIMAL(10, 2) NOT NULL,     -- Subtotal calculado (precio * cantidad)
    idpedido INT NOT NULL,                -- Pedido al que pertenece el detalle
    FOREIGN KEY (idproducto) REFERENCES productos(id),
    FOREIGN KEY (idpedido) REFERENCES pedidos(id)
        ON DELETE CASCADE
);

-- Tabla de administradores
CREATE TABLE IF NOT EXISTS administradores (
    id INT AUTO_INCREMENT PRIMARY KEY,
    dni VARCHAR(8) NOT NULL UNIQUE,
    nombre VARCHAR(255) NOT NULL,
    apellido VARCHAR(255) NOT NULL,
    username VARCHAR(255) NOT NULL UNIQUE,
    contrasena VARCHAR(255) NOT NULL,
    habilitado TINYINT DEFAULT 1
);

-- --- Índices (al final del script) ---

-- Índice en las columnas codigo y nombre para búsqueda por nombre o código de producto
CREATE INDEX idx_producto_codigo_nombre ON productos(codigo, nombre);

-- Índice en la columna idcategoria para búsqueda por categoría
CREATE INDEX idx_producto_categoria ON productos(idcategoria);

-- Índice en la columna idproducto para búsqueda por producto (imágenes)
CREATE INDEX idx_imagenes_producto ON imagenes(idproducto);

-- Índice en la columna idestado para búsqueda por estado de pedido
CREATE INDEX idx_pedido_idestado ON pedidos(idestado);

-- Índice en la columna idpedido para búsqueda por pedido (detalles de pedido)
CREATE INDEX idx_detalles_pedido_idpedido ON detalles_pedidos(idpedido);

-- Índice en la columna idmarca para búsqueda por marca
CREATE INDEX idx_marca_id ON marcas(id);

-- Índice en la columna idcategoria para búsqueda por categoría
CREATE INDEX idx_categoria_id ON categorias(id);

